import json,pathlib
P=pathlib.Path(__file__).resolve().parent;d=json.loads((P/'inferencia-espacial-resultado.json').read_text())
assert 'national_flows_all_models' in d
html=r'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inferência ecológica espacial · Brasil</title><style>body{margin:0;background:#edf3f7;color:#172f40;font:15px system-ui}main{max-width:1400px;margin:auto;padding:22px}header,section{background:white;padding:24px;border-radius:16px;margin-bottom:18px}h1{margin:8px 0}h2{font-size:22px}.warn{padding:16px;border-left:5px solid #d78d13;background:#fff5df}p,li{line-height:1.6}small{color:#4b6273;line-height:1.6}.scroll{overflow:auto}table{border-collapse:collapse;width:100%}td,th{padding:11px 8px;text-align:right;border-bottom:1px solid #dce5ec;white-space:nowrap}td:first-child,th:first-child{text-align:left}.controls{display:flex;flex-wrap:wrap;gap:18px;margin:18px 0}select,button{padding:10px;font:inherit;border:1px solid #b7c7d3;background:white;border-radius:8px}label{display:flex;align-items:center;gap:8px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:18px}.card{padding:16px;border:1px solid #dce5ec;border-radius:12px}.card h3{margin:0 0 10px}.kpis{display:flex;gap:24px;flex-wrap:wrap}.kpis b{display:block;font-size:28px}svg{width:100%;height:auto}a{color:#075985}@media(max-width:600px){main{padding:10px}header,section{padding:16px}}</style><main><header><small>MODELO ESPACIAL EXPLORATÓRIO · BASE 2026 DO REPOSITÓRIO</small><h1>Transferências estimadas por candidato</h1><p>Combinação da composição do primeiro turno, totais dos finalistas no segundo turno e vizinhança territorial. Ajuste nacional e por UF, seguido de comparação entre IDW² e krigagem ordinária de coeficientes ecológicos locais.</p><div class="warn"><b>Não há percentual de acerto das migrações.</b> Os erros abaixo medem previsões dos totais dos finalistas em seções reservadas para teste. Os fluxos individuais não são observados. O modelo é aproximado, e a convergência numérica não foi atingida em todos os ajustes; as taxas são provisórias. Não se declara máximo probabilístico certificado. As fontes derivadas do repositório não foram autenticadas novamente no TSE nesta etapa.</div></header>
<section><h2>Cobertura e separação espacial</h2><div class="kpis" id="coverage"></div><p id="split"></p><small>Seções sem coordenadas e exterior usam fallback regional ajustado apenas com dados de treino; ficam fora das métricas do teste espacial. Células de 0,5° não são divididas entre treino, seleção e teste. Não há faixa de exclusão entre células vizinhas; portanto, isso não garante independência espacial completa.</small></section>
<section><h2>Qual combinação generalizou melhor?</h2><p>Seleção pelo menor erro ponderado na amostra de seleção. A amostra de teste foi reservada. Os erros usam pontos percentuais de participação nos votos do universo contábil da seção, incluindo comparecimento e abstenção; não apenas votos válidos.</p><div class="scroll" id="models"></div><p id="winner"></p><small>MAE ponderado = 100 × soma dos erros absolutos de Lula e Flávio ÷ (2 × soma do universo das seções). P95 e máximo são dos erros absolutos por seção/finalista. Não converter 1 − erro em “taxa de acerto da migração”.</small></section>
<section><h2>Taxas estimadas, peso de origem e destinos</h2><div class="controls"><label>Recorte <select id="territory"><option value="BR">Brasil + exterior</option><option value="BRonly">Brasil sem exterior</option></select></label><label>Exibição <select id="flowMode"><option value="flow">Estimativa estatística · resíduos visíveis</option><option value="calibrated_flow">Conciliação com totais conhecidos do 2º turno</option></select></label></div><p id="tableNote"></p><div class="scroll" id="rates"></div><small>Peso no 1º turno: votos da candidatura ÷ soma dos votos das candidaturas incluídas. Peso entre eliminados: votos da candidatura ÷ votos dos eliminados. Para finalistas, a coluna do próprio candidato significa permanência. “Outros” reúne brancos, nulos, abstenção e resíduo cadastral. Percentuais usam os votos da própria origem; soma até 100% antes do arredondamento.</small><p><button id="exportCSV">Baixar tabela CSV</button></p></section>
<section><h2>Totais dos finalistas: estimado versus registrado</h2><p>No modo estatístico, o modelo não foi forçado a reproduzir os destinos finais. No modo de conciliação, utiliza-se explicitamente o resultado conhecido para fechar as margens. As diferenças abaixo mostram o resíduo do ajuste no recorte selecionado; incluem seções de treino e teste e não substituem a avaliação fora da amostra.</p><div id="finals" class="scroll"></div></section>
<section><h2>Origens completas → destinos do segundo turno</h2><p>Inclui votos em cada candidato, brancos, nulos e abstenções do primeiro turno. Cada célula mostra votos e percentual da origem. Ajuste de universo é categoria contábil, não eleitor identificado.</p><div class="scroll" id="fullMatrix"></div><h2>Reconstrução dos totais finais</h2><div id="reconstruction" class="scroll"></div><p id="reconciliationNote"></p></section><section><h2>Quanto da diferença veio de cada origem?</h2><p>Participação na variação = 100 × contribuição líquida da origem ÷ (votos registrados no 2º turno − votos registrados no 1º turno). Contribuição líquida = entradas estimadas da origem menos saídas estimadas para ela. Pode ser negativa ou maior que 100%; o resíduo do ajuste é separado e não representa migração observada.</p><div id="deltaContributions" class="scroll"></div></section><section><h2>Histogramas estaduais da transferência estimada</h2><p>Faixas de 5 pontos percentuais. Os coeficientes variam por bloco geográfico; seções de um mesmo bloco compartilham as taxas estimadas. Valores não são observações de comportamento individual.</p><div class="controls"><label>Candidato <select id="candidate"></select></label><label>Destino <select id="destination"><option value="1">Flávio</option><option value="0">Lula</option></select></label><label>Ponderação <select id="weight"><option value="urnas">Número de seções</option><option value="votos_origem">Votos da origem</option></select></label></div><div class="grid" id="histograms"></div><small>Escalas verticais próprias por estado. Última faixa inclui 100%. Sem votos de origem, a seção não entra no histograma.</small></section>
<section><h2>Variograma e krigagem ordinária</h2><p>A krigagem interpola cinco log-razões das taxas estimadas por candidatura em blocos de treino, em relação ao modelo da UF. Variograma esférico isotrópico por UF, ajustado a campos de coeficientes padronizados. Distância de corda em esfera terrestre, em quilômetros.</p><label>UF <select id="variogramUF"></select></label><div id="variogram"></div><p>O IDW² usa pesos proporcionais a 1/distância². A krigagem resolve o sistema de covariâncias com soma dos pesos igual a 1; pesos podem ser negativos. As log-razões são transformadas de volta para taxas não negativas com soma 100%.</p><small>Variância condicional de krigagem não inclui incerteza dos coeficientes ecológicos, seleção de variograma ou identidade dos eleitores. Não representa margem de erro total das migrações. Não foram demonstradas estacionariedade plena ou anisotropia.</small></section>
<section><h2>Dependência da escolha do modelo</h2><p>Intervalo abaixo = mínimo–máximo entre as cinco especificações testadas. É sensibilidade, não intervalo de confiança, e pode subestimar outras fontes de incerteza.</p><div id="sensitivity" class="scroll"></div></section>
<section><h2>Auditoria e limites</h2><div id="diagnostics"></div><ul><li>Ajuste ecológico usa pseudoverossimilhança multinomial agregada, não a verossimilhança exata de trajetórias individuais.</li><li>O modelo de vizinhança é uma exploração finita de especificações; não enumera todas as combinações nem prova o máximo global.</li><li>Colinearidade entre candidaturas e poucos votos de algumas origens podem produzir taxas extremas e pouco identificadas.</li><li>Os 43 registros não conferidos da base inicial ficaram fora do ajuste. O universo comum por seção é uma construção contábil; igualdade de cadastro não comprova identidade dos eleitores.</li><li>Coordenadas e coeficientes são agregados em blocos; não se trata de krigagem pontual do comportamento de cada eleitor.</li></ul><p>Fonte: arquivos derivados em dados/2026, repositório fabiooliveira-source/paineleleitoral-2026, referência 104b8adbecbee2261b9b4883eb46ef6352996dd4. Coordenadas originadas, segundo o manifesto do repositório, de eleitorado_local_votacao_2026.zip.</p><p>Confiança alta nas invariantes contábeis e na comparação numérica desta execução. Confiança limitada na interpretação comportamental das taxas.</p><button id="exportJSON">Baixar resultados e diagnósticos JSON</button></section></main>
<script>const DATA=__DATA__;
const $=id=>document.getElementById(id),fmt=n=>Math.round(n).toLocaleString('pt-BR'),num=n=>n.toFixed(3).replace('.',','),pc=(n,b)=>b?(100*n/b).toFixed(2).replace('.',',')+'%':'—',modelName=m=>m.method==='UF'?'UF regularizado':m.method==='IDW2'?'IDW² · '+m.k+' vizinhos':'Krigagem ordinária · '+m.k+' vizinhos';
function table(h,rows){return '<table><thead><tr>'+h.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function selectedStates(){const t=$('territory').value;return DATA.by_uf.filter(s=>t==='BR'||t==='BRonly'&&s.uf!=='ZZ'||t===s.uf)}
function aggregate(){const ss=selectedStates(),origin=DATA.origins.map((_,i)=>ss.reduce((a,s)=>a+s.origin[i],0)),flow=DATA.origins.map((_,i)=>DATA.destinations.map((_,j)=>ss.reduce((a,s)=>a+s[$('flowMode').value][i][j],0))),observed=DATA.destinations.map((_,j)=>ss.reduce((a,s)=>a+s.observed_second[j],0));return {ss,origin,flow,observed}}
function renderTable(){const {ss,origin:a,flow:f,observed}=aggregate(),valid=a.slice(0,DATA.codes.length).reduce((a,b)=>a+b,0),eliminated=a.slice(2,DATA.codes.length).reduce((a,b)=>a+b,0);$('rates').innerHTML=table(['Candidatura · 1º turno','Votos de origem','Peso no 1º turno','Peso entre eliminados','→ Flávio · %','→ Lula · %','Outros · %','→ Flávio · votos','→ Lula · votos'],DATA.origins.map((c,i)=>[DATA.origins[i],fmt(a[i]),i<DATA.codes.length?pc(a[i],valid):'—',i<2||i>=DATA.codes.length?'—':pc(a[i],eliminated),pc(f[i][1],a[i]),pc(f[i][0],a[i]),pc(f[i].slice(2).reduce((x,y)=>x+y,0),a[i]),fmt(f[i][1]),fmt(f[i][0])]));$('tableNote').textContent=modelName(DATA.selected)+' · '+($('flowMode').value==='flow'?'estimativa sem conciliação':'conciliação contábil posterior')+' · '+fmt(ss.reduce((a,s)=>a+s.sections,0))+' seções no recorte. Votos são estimativas fracionárias, arredondadas na exibição.';const fitted=DATA.destinations.map((_,j)=>f.reduce((a,r)=>a+r[j],0));$('finals').innerHTML=table(['Finalista','Total registrado na base','Total estimado','Diferença em votos','Diferença relativa'],[1,0,2,3,4,5].map(j=>[DATA.destinations[j],fmt(observed[j]),fmt(fitted[j]),fmt(fitted[j]-observed[j]),pc(fitted[j]-observed[j],observed[j])])) ;renderFullMatrix();renderDelta()}

function renderFullMatrix(){const {origin:a,flow:f,observed}=aggregate();$('fullMatrix').innerHTML=table(['Origem 1º turno','Base',...DATA.destinations.map(n=>'→ '+n)],DATA.origins.map((name,i)=>[name,fmt(a[i]),...f[i].map(v=>fmt(v)+' ('+pc(v,a[i])+')')]));$('reconstruction').innerHTML=table(['Finalista','Base no 1º turno','Entradas de outras origens','Saídas para outros destinos','Total reconstruído','Total registrado','Resíduo registrado − estimado'],[1,0].map(j=>{const entries=f.reduce((n,row,i)=>n+(i!==j?row[j]:0),0),exits=f[j].reduce((n,v,k)=>n+(k!==j?v:0),0),total=a[j]+entries-exits;return [DATA.destinations[j],fmt(a[j]),fmt(entries),fmt(exits),fmt(total),fmt(observed[j]),fmt(observed[j]-total)]}));$('reconciliationNote').textContent=$('flowMode').value==='flow'?'Estimativa original preservada: total final = base do 1º turno + entradas − saídas + resíduo do ajuste. O resíduo não é migração identificada.':'Conciliação posterior: margens ajustadas aos totais conhecidos do 2º turno por IPF, preservando as origens. O fechamento exato é contábil; não comprova as transferências nem modifica os erros fora da amostra.';}


function renderDelta(){const {origin:a,flow:f,observed}=aggregate();$('deltaContributions').innerHTML=[1,0].map(j=>{const delta=observed[j]-a[j];const rows=[];let netSum=0;DATA.origins.forEach((name,i)=>{if(i===j)return;const destination=i<2?i:i>=DATA.codes.length?i-DATA.codes.length+2:-1;const incoming=f[i][j],outgoing=destination>=0?f[j][destination]:0,net=incoming-outgoing;netSum+=net;rows.push([name,fmt(incoming),fmt(outgoing),fmt(net),pc(net,delta)])});const fitted=f.reduce((n,r)=>n+r[j],0),residual=observed[j]-fitted;rows.push(['Resíduo do modelo · não é migração','—','—',fmt(residual),pc(residual,delta)]);rows.push(['Total da variação','—','—',fmt(netSum+residual),pc(netSum+residual,delta)]);return '<h3>'+DATA.destinations[j]+' · diferença registrada: '+fmt(delta)+' votos</h3>'+table(['Origem','Entradas estimadas','Saídas estimadas','Contribuição líquida','% da diferença registrada'],rows)}).join('')}

function renderHist(){const c=$('candidate').value,j=+$('destination').value,w=$('weight').value;$('histograms').innerHTML=DATA.by_uf.map(s=>{const h=s.histograms[c][j][w],max=Math.max(1,...h);let svg='<svg viewBox="0 0 340 205" role="img" aria-label="Histograma '+s.uf+'"><text x="34" y="16" font-size="11">Máximo: '+fmt(max)+'</text><line x1="34" x2="330" y1="165" y2="165" stroke="#91a3b0"/>';h.forEach((v,k)=>{const ht=130*v/max;svg+='<rect tabindex="0" x="'+(35+k*14.5)+'" y="'+(165-ht)+'" width="12" height="'+Math.max(.2,ht)+'" fill="'+(j===1?'#14805b':'#bf3044')+'"><title>'+k*5+'–'+(k+1)*5+'%: '+fmt(v)+'</title></rect>'});for(let k=0;k<5;k++)svg+='<text x="'+(34+k*72.5)+'" y="185" font-size="11">'+k*25+'%</text>';return '<article class="card"><h3>'+s.uf+(s.uf==='ZZ'?' · Exterior':'')+'</h3><small>'+fmt(h.reduce((a,b)=>a+b,0))+' '+(w==='urnas'?'seções com votos da origem':'votos de origem')+'</small>'+svg+'</svg></article>'}).join('')}
function renderVariogram(){const v=DATA.variograms[$('variogramUF').value];if(v.fallback){$('variogram').textContent='Sem variograma ajustado: '+v.fallback;return}const maxX=Math.max(...v.bins.map(r=>r[0])),maxY=Math.max(1,v.nugget+v.partial_sill,...v.bins.map(r=>r[1]))*1.15;const x=t=>50+t/maxX*670,y=t=>260-t/maxY*220;let svg='<svg viewBox="0 0 760 310" role="img" aria-label="Variograma esférico e pontos empíricos"><line x1="50" x2="720" y1="260" y2="260" stroke="#789"/><line x1="50" x2="50" y1="30" y2="260" stroke="#789"/>';let path='';for(let i=0;i<=100;i++){const h=maxX*i/100,t=Math.min(h/v.range_km_chord,1),g=v.nugget+v.partial_sill*(1.5*t-.5*t*t*t);path+=(i?' L':'M')+x(h)+' '+y(g)}svg+='<path d="'+path+'" stroke="#075985" fill="none" stroke-width="2"/>';for(const [h,g,n] of v.bins)svg+='<circle cx="'+x(h)+'" cy="'+y(g)+'" r="4" fill="#d27617"><title>Distância '+num(h)+' km; semivariância '+num(g)+'; '+n+' pares</title></circle>';svg+='<text x="50" y="290">0 km</text><text x="650" y="290">'+fmt(maxX)+' km</text><text x="10" y="30">'+num(maxY)+'</text></svg>';$('variogram').innerHTML='<p>Pepita '+num(v.nugget)+' · contribuição '+num(v.partial_sill)+' · alcance '+num(v.range_km_chord)+' km · '+v.active_coefficient_fields+' campos padronizados usados.</p>'+svg}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const c=DATA.counts;$('coverage').innerHTML=[['Seções modeladas',c.sections],['Com coordenadas',c.geocoded],['Sem coordenadas / exterior',c.unmapped_including_exterior],['Células geográficas',c.geographical_cells]].map(([n,v])=>'<div><b>'+fmt(v)+'</b>'+n+'</div>').join('');$('split').textContent='Treino: '+fmt(c.train)+' seções · seleção: '+fmt(c.tuning)+' · teste: '+fmt(c.test)+'.';$('models').innerHTML=table(['Modelo','MAE ponderado · seleção','MAE ponderado · teste','MAE simples · teste','P95 · teste','Máximo · teste'],DATA.models.map((m,i)=>[(i===DATA.selected_index?'✓ ':'')+modelName(m),num(m.tuning.weighted_mae_pp)+' pp',num(m.test.weighted_mae_pp)+' pp',num(m.test.mae_pp)+' pp',num(m.test.p95_pp)+' pp',num(m.test.max_pp)+' pp']));$('winner').textContent='Selecionado: '+modelName(DATA.selected)+'. A melhora do erro não valida a origem individual dos votos.';
for(const s of DATA.by_uf)$('territory').add(new Option(s.uf,s.uf));DATA.codes.forEach((c,i)=>$('candidate').add(new Option(DATA.origins[i]+' · '+c,c)));$('candidate').value='70';for(const uf of Object.keys(DATA.variograms))if(uf!=='ZZ')$('variogramUF').add(new Option(uf,uf));$('variogramUF').value='BA';$('territory').onchange=renderTable;$('flowMode').onchange=renderTable;for(const id of ['candidate','destination','weight'])$(id).onchange=renderHist;$('variogramUF').onchange=renderVariogram;
$('sensitivity').innerHTML=table(['Origem','→ Flávio · mínimo–máximo','→ Lula · mínimo–máximo'],DATA.codes.map((c,i)=>{const vals=DATA.national_flows_all_models.map(f=>[f[i][1]/DATA.national_origin[i],f[i][0]/DATA.national_origin[i]]);return [DATA.origins[i],pc(Math.min(...vals.map(v=>v[0])),1)+' – '+pc(Math.max(...vals.map(v=>v[0])),1),pc(Math.min(...vals.map(v=>v[1])),1)+' – '+pc(Math.max(...vals.map(v=>v[1])),1)]}));const gd=DATA.global_fit_diagnostic,ufds=Object.values(DATA.UF_fit_diagnostics),conv=ufds.filter(d=>d.converged_step_1e7).length;$('diagnostics').textContent='Ajuste nacional: '+gd.iterations+' iterações; maior mudança final '+gd.last_max_delta.toExponential(3)+'; convergiu no limiar definido: '+(gd.converged_step_1e7?'sim':'não')+'. UFs que atingiram o limiar: '+conv+'/'+ufds.length+'. Testes sintéticos de soma dos pesos e reprodução de constante da krigagem passaram. Taxas respeitam 0–100% e conservam origens.';
$('exportJSON').onclick=()=>download('inferencia-espacial-resultado.json',JSON.stringify(DATA,null,2),'application/json');$('exportCSV').onclick=()=>{const {origin:a,flow:f}=aggregate();const rows=[['Candidatura','Base_1t','Flavio_pct','Lula_pct','Outros_pct','Flavio_votos','Lula_votos'],...DATA.origins.map((c,i)=>[DATA.origins[i],a[i],pc(f[i][1],a[i]),pc(f[i][0],a[i]),pc(f[i].slice(2).reduce((x,y)=>x+y,0),a[i]),f[i][1],f[i][0]])];download('inferencia-espacial-por-candidato.csv','\uFEFF'+rows.map(r=>r.join(';')).join('\n'),'text/csv')};renderTable();renderHist();renderVariogram();</script></html>'''
(P/'inferencia-espacial-brasil.html').write_text(html.replace('__DATA__',json.dumps(d,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')))
print((P/'inferencia-espacial-brasil.html').stat().st_size)
